// Baseline provider response for generator/engine journeys; the critic-specific journey has its own paired baseline fixture.
export const theme = html => html.replace(/<body\b[^>]*>/i, '$&<style>:root{color-scheme:light dark}body{background:light-dark(#fff,#111);color:light-dark(#111,#eee);font:16px system-ui;margin:0;padding:16px;box-sizing:border-box}*{box-sizing:border-box}</style>');
export const landingPage = (visual = '<figure><div class="screen">Umer’s launch checklist: review the release notes.</div></figure>') => theme(`<!doctype html><html><head><title>Umer notes</title><style>section{padding:64px 20px;max-width:1040px;margin:auto}h1{font-size:36px;margin:0 0 16px;max-width:18ch}h2{margin:0 0 16px}p{margin:0 0 24px;max-width:60ch}.primary{display:inline-block;background:#2563eb;color:white;padding:12px 20px;text-decoration:none}figure{margin:32px 0 0}.screen{padding:32px;border:1px solid #aaa}img{max-width:100%;height:140px;object-fit:contain}</style></head><body><section id="hero" data-section="hero"><h1>Clear notes for teams who ship</h1><p>Umer’s checklist and release notes in one place.</p><a class="primary" data-cta="primary" href="#proof">Open your notes</a>${visual}</section><section id="proof" data-section="proof"><h2>A sample release, kept together</h2><p>Sample: Umer keeps the launch checklist beside its release notes.</p></section></body></html>`);
export const flowPage = () => theme('<!doctype html><html><head><style>section{height:calc(100dvh - 32px);display:flex;flex-direction:column}header{height:40px;display:flex;justify-content:space-between}h1{font-size:28px;margin:16px 0}p{margin:8px 0}img{width:calc(100% + 32px);margin-left:-16px;height:50dvh;object-fit:cover;mask-image:linear-gradient(#000 70%,transparent)}footer{margin-top:auto;display:flex;justify-content:space-between;align-items:center}a{display:inline-flex;min-height:44px;min-width:44px;align-items:center}</style></head><body>' + ['welcome','mood','ready'].map((id,i)=>`<section data-oc-screen="${id}" id="${id}"><header>${i<2?`<a href="#${i?'welcome':id}">Back</a><a href="#ready">Skip</a>`:''}</header><p>${['Welcome','Your mood','Ready to begin'][i]}</p><h1>${['Welcome to Mellow','Choose your mood','Ready for today'][i]}</h1><img alt="${id}" src="assets/${id}-${i+2}.webp"><footer><span>${i+1} / 3</span><a href="#${['mood','ready','ready'][i]}">${i===2?'Get started':'Next'}</a></footer></section>`).join('') + '</body></html>');
export function plainPage(res, body) {
  if (!body.includes('"write_page"')) return false;
  const item = { type: 'function_call', id: 'fc-plain', call_id: 'c-plain', name: 'write_page', arguments: JSON.stringify({ html: theme('<!doctype html><html><body><h1>Umer notes</h1></body></html>') }) };
  const ev = data => `event: ${data.type}\ndata: ${JSON.stringify(data)}\n\n`;
  res.writeHead(200, { 'content-type': 'text/event-stream' });
  res.end(ev({ type: 'response.output_item.added', output_index: 0, item }) + ev({ type: 'response.output_item.done', output_index: 0, item }) + ev({ type: 'response.completed', response: { id: 'r-plain', status: 'completed', usage: { input_tokens: 0, output_tokens: 0, total_tokens: 0 } } }));
  return true;
}
